import { Component, createEffect, createSignal, Match, Show, Switch } from "solid-js";

import {
	getRelationshipIconFromPlayer,
	getWarStatusFromPlayerId,
	WarStatus,
} from "#core/ui/utilities/diplomacy-utilities.js";
import { getPlayerColorVariants, isPrimaryColorLighter } from "#core/ui/utilities/utilities-color.js";
import { Icon } from "#core/ui/utilities/utilities-image.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { multiplayerTeamColors } from "#core/ui/utilities/utilities-network-constants.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { PortraitIcon, PortraitIconData } from "#core/ui-next/components/portrait-icon.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { getSettlementIconInfo } from "#core/ui-next/utilities/settlement-utilities.js";

import { RelationshipTooltip } from "#base/ui-next/tooltips/relationship-tooltip.jsx";

export interface LeaderTileData {
	iconSizeClass?: string;
	/** Optional additional class for the ribbon, useful for sizing */
	ribbonClass?: string;
	leaderId: number;
	size: number;
	cityId?: ComponentID;
	representsCityState?: boolean;
	omitFullRibbon?: boolean;
	omitRelationshipIcon?: boolean;
}

const LeaderWithRibbonComponent: Component<LeaderTileData> = (props) => {
	const [tileProps, setTileProps] = createSignal<PortraitIconData>({ playerId: -1, size: 20 });
	const [bannerColor, setBannerColor] = createSignal<string>("");
	const [playerConfig, setPlayerConfig] = createSignal<ConfigurationPlayerAccessor>();
	const [civSymbol, setCivSymbol] = createSignal<string>("");
	const [civSymbolColor, setCivSymbolColor] = createSignal<string>("");
	const [relationshipIcon, setRelationshipIcon] = createSignal<string>("");
	const [warStatusWithLocalPlayer, setWarStatusWithLocalPlayer] = createSignal<WarStatus>();
	const [settlementName, setSettlementName] = createSignal<string>("");
	const [playerName, setPlayerName] = createSignal<string>("");
	const omitRelationshipIcon = () =>
		props.omitRelationshipIcon ||
		props.leaderId === GameContext.localPlayerID ||
		props.leaderId === PlayerIds.NO_PLAYER;
	createEffect(() => {
		setTileProps({
			playerId: props.leaderId,
			size: props.size,
		});

		if (props.leaderId === PlayerIds.NO_PLAYER) {
			return;
		}

		setRelationshipIcon(getRelationshipIconFromPlayer(props.leaderId));
		const player = Players.get(props.leaderId);
		if (!player) {
			return;
		}
		setPlayerName(Locale.compose(player.name));
		const variants = getPlayerColorVariants(props.leaderId);

		if (variants) {
			setBannerColor(variants.primaryColor.moreColor);
		}
		if (props.cityId) {
			const iconProperities = getSettlementIconInfo(props.cityId);
			if (iconProperities) {
				setCivSymbol(iconProperities.icon);
				setCivSymbolColor(iconProperities.color);
			}
			const city = Cities.get(props.cityId);
			if (city) {
				setSettlementName(Locale.compose(city.name));
			}
		} else {
			setCivSymbol(Icon.getCivSymbolFromCivilizationType(player.civilizationType));
		}

		setPlayerConfig(Configuration.getPlayer(props.leaderId));

		setWarStatusWithLocalPlayer(getWarStatusFromPlayerId(props.leaderId));
	});

	const Portrait = (
		<>
			<div class="relative flex flex-col top-0 items-center justify-center">
				<PortraitIcon {...tileProps()} />
				<div
					class="absolute -bottom-2 w-18 h-9 bg-contain bg-center bg-no-repeat self-center"
					classList={{
						hidden: relationshipIcon() === "" || omitRelationshipIcon(),
					}}
					style={{ "background-image": relationshipIcon() }}
				/>
			</div>
			<Show when={warStatusWithLocalPlayer()}>
				{(warStatus) => (
					<Show when={warStatus().isAtWar && !props.omitFullRibbon}>
						<div
							class="relative pointer-events-auto self-center flex justify-center items-center font-base text-2xs -ml-px w-11 h-3\\.5"
							classList={{
								"bg-positive-light": warStatus().warSupport > 0,
								"bg-negative-light": warStatus().warSupport < 0,
							}}
						>
							<L10n.Compose text={warStatus().warSupport.toString()} />
						</div>
					</Show>
				)}
			</Show>
		</>
	);

	return (
		<div
			class="z-0 relative flex flex-col items-center justify-center"
			classList={{
				"primary-color-is-lighter": isPrimaryColorLighter(props.leaderId),
				"local-player": props.leaderId === GameContext.localPlayerID,
			}}
			data-name="Leader-Tile"
		>
			<Switch fallback={Portrait}>
				<Match when={props.representsCityState}>
					<Tooltip.Text
						header="LOC_CIVILIZATION_CITY_STATE_NAME"
						text="LOC_COMMERCE_TRADE_ROUTE_CITY_STATE_TOOLTIP"
						args={[settlementName(), playerName()]}
					>
						<PortraitIcon {...tileProps()} />
					</Tooltip.Text>
				</Match>
				<Match when={!omitRelationshipIcon()}>
					<RelationshipTooltip playerId={props.leaderId}>{Portrait}</RelationshipTooltip>
				</Match>
			</Switch>
			<Show when={!props.omitFullRibbon}>
				<div
					class={`-z-1 relative ml-2 mr-1\\.5 ${props.representsCityState ? "min-h-21" : "min-h-24"} flex-1 flex flex-row justify-center self-stretch -mt-10 ${props.ribbonClass ?? ""}`}
				>
					<div
						class="absolute inset-0"
						style={{
							"border-image-slice": "40 31 31 31 fill",
							"border-image-width": `${Layout.pixels(40)} ${Layout.pixels(31)} ${Layout.pixels(31)} ${Layout.pixels(31)}`,
							"border-image-source": "url(blp:hud_frontbanner)",
							// eslint-disable-next-line solid/style-prop
							"fxs-border-image-tint": props.representsCityState ? "white" : bannerColor(),
						}}
					/>
					<div
						class="absolute inset-0"
						style={{
							"border-image-source": "url('blp:hud_frontbanner_shadow')",
							"border-image-slice": "40 31 31 31 fill",
							"border-image-width": `${Layout.pixels(40)} ${Layout.pixels(31)} ${Layout.pixels(31)} ${Layout.pixels(31)}`,
						}}
					/>
					<div
						class="absolute inset-0"
						style={{
							"border-image-source": "url('blp:hud_frontbanner_overlay')",
							"border-image-slice": "1 31 29 31 fill",
							"border-image-width": `${Layout.pixels(1)} ${Layout.pixels(31)} ${Layout.pixels(29)} ${Layout.pixels(31)}`,
						}}
					/>
					<div
						class={`bg-contain bg-center bg-no-repeat relative self-end mb-5 ${props.iconSizeClass ?? "size-9"}`}
						style={{
							"background-image": civSymbol().startsWith("url") ? civSymbol() : `url('${civSymbol()}')`,
							// eslint-disable-next-line solid/style-prop
							"fxs-background-image-tint": civSymbolColor(),
						}}
					/>
					<Show
						when={
							(Configuration.getGame().isNetworkMultiplayer || Configuration.getGame().isHotseat) &&
							Game.Diplomacy.hasTeammate(props.leaderId) &&
							playerConfig() !== undefined
						}
					>
						<div
							class="relative bg-center bg-full bg-no-repeat"
							style={{
								"--multiplayer-team-colors": multiplayerTeamColors[playerConfig()!.team + 1],
							}}
						/>
						<div class="relative font-body-base text-white text-shadow">
							{(playerConfig()!.team + 1).toString()}
						</div>
					</Show>
				</div>
			</Show>
		</div>
	);
};

export const LeaderWithRibbon = ComponentRegistry.register({
	name: "LeaderWithRibbon",
	createInstance: LeaderWithRibbonComponent,
});
